from .factory import SbtsIMSnapshotCollectorFactory, SbtsIMLogCollectorFactory
from taf.collectors.core import core
import logging

logger = logging.getLogger(__name__)
logger.addHandler(logging.NullHandler())


class infomodel(core):
    ROBOT_LIBRARY_SCOPE = 'TEST SUITE'

    def _create_im_collector(self, factory_type, parameters):
        factory_class = {"SbtsIMSnapshot": SbtsIMSnapshotCollectorFactory,
                         "SbtsIMLog": SbtsIMLogCollectorFactory}
        configuration = {}
        for parameter in parameters.keys():
            if parameters[parameter] is not None:
                configuration[parameter] = parameters[parameter]
        logger.info("Creating {} Collector with alias name: ".format(factory_type) + configuration['name'])
        im_collector = factory_class[factory_type]().create(configuration=configuration,
                                                            existing_arguments={})
        self.set_alias(parameters['name'], im_collector)
        logger.info("{} Collector created successfully".format(factory_type))

    def create_sbts_im_snapshot_collector(self, name, webservice, timeout=None, target_file_name=None):
        """
            Create snapshot collector for infomodel from given configuration.

            :param str name: alias name of the collector
            :param dict webservice: ADMIN API setup info, see `setup_admin <https://\
                                    taf-sbts-oam-coam-admin.docs.taf.ute.nsn-rdnet.net/en/latest/interfaces/\
                                    interface.html#taf.sbts.oam.coam.admin.interface.admin.setup_admin>`_,
                                    additionally the following parameter name abbreviations are supported:
                                     * "host" instead of "bts_host"
                                     * "port" instead of "bts_port"
                                     * "user" instead of "username"
            :param str target_file_name: (optional) file name part of the path under which the zip file is stored
                                        locally during collect_collectors, default value: "im_snapshot.ims2"

            :return: created object of CoamIMSnapshotCollector
            :rtype: CoamIMSnapshotCollector

            For more detail on Collectors please refer:
            https://confluence.int.net.nokia.com/display/CV/_Collector+Concepts
        """
        self._create_im_collector(factory_type='SbtsIMSnapshot',
                                  parameters={"name": name, "webservice": webservice, "timeout": timeout,
                                              "target_file_name": target_file_name})

    def create_sbts_im_log_collector(self, name, webservice, timeout=None, target_file_name=None):
        """
            Create IM log Collector for infomodel from given configuration.

            :param name: alias name of the collector
            :param dict webservice: ADMIN API setup info, see `setup_admin <https://\
                                    taf-sbts-oam-coam-admin.docs.taf.ute.nsn-rdnet.net/en/latest/interfaces/\
                                    interface.html#taf.sbts.oam.coam.admin.interface.admin.setup_admin>`_,
                                    additionally the following parameter name abbreviations are supported:
                                     * "host" instead of "bts_host"
                                     * "port" instead of "bts_port"
                                     * "user" instead of "username"
            :param float timeout: (optional) Timeout in seconds for the cOAM admin api response, default value: 480
            :param str target_file_name: (optional) file name part of the path under which the zip file is stored
                                        locally during collect_collectors, default: "im_log.ims2"

            :return: created object of CoamIMLogCollector
            :rtype: CoamIMLogCollector

            For more detail on Collectors please refer: https://confluence.int.net.nokia.com/display/CV/Collectors
        """
        self._create_im_collector(factory_type='SbtsIMLog',
                                  parameters={"name": name, "webservice": webservice, "timeout": timeout,
                                              "target_file_name": target_file_name})
